from taf.gnb.oam.coam.cu.utilities.http_client import HttpClient


class TRSLicensedv1HttpClient(HttpClient):
    """ This class provides a client for the TRS Licensed v1 API. """

    def __init__(self, base_url, connection_alias):
        super(TRSLicensedv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/licensed/v1"

    def abort_ip_traffic_capture(self, timeout=30):
        endpoint= '/ip-traffic-capture/abort'
        headers = {
            "accept": "*/*",
        }
        self._send_post_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def start_ip_traffic_capture(self, capture_type, measurement_point, plane_type, pod_names, timeout=30):
        endpoint = "/ip-traffic-capture/start"
        headers = {
            "accept": "*/*",
            "Content-Type": "application/json",
        }
        json_data = {
            "captureType": capture_type,
            'measurementPoint': measurement_point,
        }

        if plane_type:
            json_data["planeType"] = plane_type
        if pod_names:
            json_data["podNames"] = pod_names

        self._send_post_request(endpoint=endpoint, headers=headers, json=json_data, timeout=timeout)

    def stop_ip_traffic_capture(self, timeout=30):
        self._send_post_request(endpoint="/ip-traffic-capture/stop",
                                headers={"accept": "*/*"},
                                timeout=timeout)

    def generate_ip_traffic_capture_files(self, credentials, timeout=30):
        endpoint = "/ip-traffic-capture/generate"
        headers = {
            "accept": "*/*",
            "Content-Type": "application/json",
        }
        json_data = {
            "credentials": credentials
        }

        return self._send_post_request(endpoint=endpoint, headers=headers, json=json_data, timeout=timeout)

    def activate_file_upload_operation(self, timeout=30):
        endpoint = "/ip-traffic-capture/files/activate-upload"
        headers = {
            "accept": "*/*",
        }
        return self._send_post_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def get_file_upload_operation(self, operation_id, timeout=30):
        endpoint = f"/ip-traffic-capture/files/activate-upload/{operation_id}"
        headers = {
            "accept": "*/*",
        }
        self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def delete_file_upload_operation(self, timeout=30):
        endpoint = "/ip-traffic-capture/files/activate-upload"
        headers = {
            "accept": "*/*",
        }
        self._send_delete_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def upload_ip_traffic_capture_file(self, operation_id, file_name, timeout=30):
        endpoint = f"/ip-traffic-capture/upload/{operation_id}/{file_name}"
        headers = {
            "accept": "application/octet-stream",
        }
        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout).content

    def get_ip_traffic_capture_status(self, timeout=30):
        endpoint = "/ip-traffic-capture/status"
        headers = {
            "accept": "application/json",
        }
        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)
